import { useState, useEffect, useMemo } from 'react';
import { attendanceService } from '../services/attendanceService';

export function useAttendanceData() {
  const [isLoading, setIsLoading] = useState(false);
  const [selectedMonth, setSelectedMonth] = useState('2024-09');
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedDepartment, setSelectedDepartment] = useState('ALL');

  const [attendanceRows, setAttendanceRows] = useState([]);
  const [summary, setSummary] = useState({
    totalEmployees: 0,
    presentEmployees: 0,
    absentEmployees: 0,
    lateLeaveEmployees: 0,
    totalLateMinutes: 0
  });
  const [reportMeta, setReportMeta] = useState({});
  const [availableMonths] = useState([
    { value: '2024-09', label: 'Tháng 9, 2024' },
    { value: '2026-04', label: 'Tháng 4, 2026' },
    { value: '2026-05', label: 'Tháng 5, 2026' },
  ]);

  const [departmentOptions, setDepartmentOptions] = useState([]);

  useEffect(() => {
    fetchData();
  }, [selectedMonth]);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const res = await attendanceService.getSummary(selectedMonth);
      if (res.success) {
        setAttendanceRows(res.data || []);
        setReportMeta({
          month: selectedMonth.split('-')[1],
          year: selectedMonth.split('-')[0],
          totalStats: res.total_stats,
          weekdayStats: res.weekday_stats
        });

        setSummary({
          totalEmployees: res.data.length,
          presentEmployees: res.data.filter(r => r.WorkDays > 0).length,
          absentEmployees: res.data.filter(r => r.AbsentDays > 0).length,
          lateLeaveEmployees: res.data.filter(r => r.LeaveDays > 0).length,
          totalLateMinutes: res.total_stats?.total_late_minutes || 0
        });

        // Extract departments
        const depts = Array.from(new Set(res.data.map(d => d.DepartmentName).filter(Boolean)));
        setDepartmentOptions(depts);
      }
    } catch (error) {
      console.error("Failed to fetch attendance data:", error);
    }
    setIsLoading(false);
  };

  const filteredAttendanceRows = useMemo(() => {
    if (selectedDepartment === 'ALL') return attendanceRows;
    return attendanceRows.filter(row => row.DepartmentName === selectedDepartment);
  }, [attendanceRows, selectedDepartment]);

  return {
    isLoading,
    selectedMonth,
    setSelectedMonth,
    selectedDate,
    setSelectedDate,
    selectedDepartment,
    setSelectedDepartment,
    attendanceRows: filteredAttendanceRows, // For AttendanceList
    reportRows: attendanceRows, // For ReportsAttendance (usually all rows then filtered there)
    filteredTodayRows: attendanceRows.filter(r => r.Status === 'Present'), // Placeholder for today logic
    summary,
    reportMeta,
    availableMonths,
    departmentOptions,
    apiUrl: 'http://localhost:5000/api/attendance'
  };
}
